CREATE TABLE "users" (
  "user_id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "email_normalized" "VARCHAR(320)" UNIQUE NOT NULL,
  "password_hash" TEXT NOT NULL,
  "first_name" "VARCHAR(100)",
  "last_name" "VARCHAR(100)",
  "birth_date" DATE,
  "phone_number" "VARCHAR(40)",
  "status" "VARCHAR(40)" NOT NULL DEFAULT 'PENDING_VERIFICATION',
  "email_verified_at" "TIMESTAMPTZ",
  "created_at" "TIMESTAMPTZ" NOT NULL DEFAULT (CURRENT_TIMESTAMP),
  "updated_at" "TIMESTAMPTZ" NOT NULL DEFAULT (CURRENT_TIMESTAMP),
  "deleted_at" "TIMESTAMPTZ"
);

CREATE TABLE "roles" (
  "role_id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "code" "VARCHAR(40)" UNIQUE NOT NULL
);

CREATE TABLE "user_roles" (
  "user_id" BIGINT NOT NULL,
  "role_id" BIGINT NOT NULL,
  PRIMARY KEY ("user_id", "role_id")
);

CREATE TABLE "auth_tokens" (
  "token_id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "user_id" BIGINT NOT NULL,
  "token_hash" TEXT UNIQUE NOT NULL,
  "purpose" "VARCHAR(40)" NOT NULL,
  "expires_at" "TIMESTAMPTZ" NOT NULL,
  "consumed_at" "TIMESTAMPTZ",
  "revoked_at" "TIMESTAMPTZ",
  "created_at" "TIMESTAMPTZ" NOT NULL DEFAULT (CURRENT_TIMESTAMP),
  CHECK (expires_at > created_at)
);

CREATE TABLE "schools" (
  "school_id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" "VARCHAR(255)" NOT NULL,
  "street" "VARCHAR(255)",
  "street_number" "VARCHAR(30)",
  "city" "VARCHAR(150)",
  "province" "VARCHAR(100)",
  "postal_code" "VARCHAR(20)"
);

CREATE TABLE "students" (
  "student_id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "user_id" BIGINT UNIQUE NOT NULL,
  "school_id" BIGINT,
  "username" "VARCHAR(80)" UNIQUE NOT NULL,
  "created_at" "TIMESTAMPTZ" NOT NULL DEFAULT (CURRENT_TIMESTAMP)
);

CREATE TABLE "guardian_links" (
  "guardian_user_id" BIGINT NOT NULL,
  "student_id" BIGINT NOT NULL,
  "relationship" "VARCHAR(60)" NOT NULL,
  "verification_status" "VARCHAR(40)" NOT NULL DEFAULT 'PENDING',
  "verified_at" "TIMESTAMPTZ",
  "created_at" "TIMESTAMPTZ" NOT NULL DEFAULT (CURRENT_TIMESTAMP),
  PRIMARY KEY ("guardian_user_id", "student_id")
);

CREATE TABLE "policy_acceptances" (
  "acceptance_id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "user_id" BIGINT NOT NULL,
  "document_code" "VARCHAR(80)" NOT NULL,
  "document_version" "VARCHAR(40)" NOT NULL,
  "acknowledged_at" "TIMESTAMPTZ" NOT NULL DEFAULT (CURRENT_TIMESTAMP)
);

CREATE TABLE "skills" (
  "skill_id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "code" "VARCHAR(60)" UNIQUE NOT NULL,
  "name" "VARCHAR(150)" NOT NULL,
  "description" TEXT,
  "status" "VARCHAR(40)" NOT NULL DEFAULT 'DRAFT'
);

CREATE TABLE "skill_levels" (
  "skill_level_id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "skill_id" BIGINT NOT NULL,
  "level_number" INTEGER NOT NULL CHECK (level_number >= 1),
  "min_points" "NUMERIC(12,2)" NOT NULL CHECK (min_points >= 0)
);

CREATE TABLE "skins" (
  "skin_id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "code" "VARCHAR(80)" UNIQUE NOT NULL,
  "name" "VARCHAR(150)" NOT NULL,
  "description" TEXT,
  "status" "VARCHAR(40)" NOT NULL DEFAULT 'DRAFT'
);

CREATE TABLE "skin_evolutions" (
  "evolution_id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "skin_id" BIGINT NOT NULL,
  "stage_number" INTEGER NOT NULL CHECK (stage_number >= 0),
  "name" "VARCHAR(150)" NOT NULL,
  "description" TEXT,
  "asset_path" TEXT NOT NULL
);

CREATE TABLE "student_skins" (
  "student_skin_id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "student_id" BIGINT NOT NULL,
  "skin_id" BIGINT NOT NULL,
  "unlocked_at" "TIMESTAMPTZ" NOT NULL DEFAULT (CURRENT_TIMESTAMP)
);

CREATE TABLE "student_skin_evolutions" (
  "student_skin_id" BIGINT NOT NULL,
  "evolution_id" BIGINT NOT NULL,
  "skin_id" BIGINT NOT NULL,
  "unlocked_at" "TIMESTAMPTZ" NOT NULL DEFAULT (CURRENT_TIMESTAMP),
  PRIMARY KEY ("student_skin_id", "evolution_id")
);

CREATE TABLE "character_selections" (
  "student_id" BIGINT PRIMARY KEY,
  "student_skin_id" BIGINT NOT NULL,
  "evolution_id" BIGINT NOT NULL,
  "selected_at" "TIMESTAMPTZ" NOT NULL DEFAULT (CURRENT_TIMESTAMP)
);

CREATE TABLE "subjects" (
  "subject_id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" text NOT NULL CHECK (btrim(name) <> '')
);

CREATE TABLE "courses" (
  "course_id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "subject_id" bigint NOT NULL,
  "title" text NOT NULL CHECK (btrim(title) <> ''),
  "short_description" text NOT NULL,
  "extended_description" text NOT NULL,
  "cover_reference" text
);

CREATE TABLE "missions" (
  "mission_id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "course_id" bigint NOT NULL,
  "title" text NOT NULL CHECK (btrim(title) <> ''),
  "short_description" text NOT NULL,
  "sort_order" integer NOT NULL CHECK (sort_order > 0)
);

CREATE TABLE "lessons" (
  "lesson_id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "mission_id" bigint NOT NULL,
  "title" text NOT NULL CHECK (btrim(title) <> ''),
  "sort_order" integer NOT NULL CHECK (sort_order > 0)
);

CREATE TABLE "lesson_pages" (
  "lesson_page_id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "lesson_id" bigint NOT NULL,
  "sort_order" integer NOT NULL CHECK (sort_order > 0),
  "kind" text NOT NULL CHECK (kind IN ('text', 'image', 'video')),
  "formatted_text" text,
  "image_reference" text,
  "video_provider" text,
  "video_identifier" text,
  CHECK ((kind = 'text' AND formatted_text IS NOT NULL
            AND image_reference IS NULL AND video_provider IS NULL
            AND video_identifier IS NULL)
        OR (kind = 'image' AND image_reference IS NOT NULL
            AND formatted_text IS NULL AND video_provider IS NULL
            AND video_identifier IS NULL)
        OR (kind = 'video' AND video_provider IS NOT NULL
            AND video_identifier IS NOT NULL AND formatted_text IS NULL
            AND image_reference IS NULL))
);

CREATE TABLE "question_bank_entries" (
  "question_bank_entry_id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "internal_title" text NOT NULL CHECK (btrim(internal_title) <> '')
);

CREATE TABLE "question_versions" (
  "question_version_id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "question_bank_entry_id" bigint NOT NULL,
  "version_number" integer NOT NULL CHECK (version_number > 0)
);

CREATE TABLE "questions" (
  "question_id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "question_version_id" bigint UNIQUE NOT NULL,
  "kind" text NOT NULL CHECK (kind IN (
        'multiple_choice', 'fill_in', 'sentence_translation', 'passage_translation'
    )),
  "prompt" text NOT NULL,
  "source_text" text,
  "general_explanation" text,
  CHECK ((kind IN ('sentence_translation', 'passage_translation')
            AND source_text IS NOT NULL AND general_explanation IS NOT NULL)
        OR (kind IN ('multiple_choice', 'fill_in') AND source_text IS NULL))
);

CREATE TABLE "question_answers" (
  "question_answer_id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "question_id" bigint NOT NULL,
  "text" text NOT NULL,
  "is_correct" boolean NOT NULL,
  "sort_order" integer NOT NULL CHECK (sort_order > 0),
  "feedback" text
);

CREATE TABLE "mission_exercises" (
  "mission_exercise_id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "mission_id" bigint NOT NULL,
  "lesson_id" bigint UNIQUE NOT NULL,
  "question_bank_entry_id" bigint NOT NULL
);

CREATE TABLE "topics" (
  "topic_id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "subject_id" bigint NOT NULL,
  "name" text NOT NULL CHECK (btrim(name) <> '')
);

CREATE TABLE "practice_exercises" (
  "practice_exercise_id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "question_bank_entry_id" bigint UNIQUE NOT NULL,
  "skill_id" bigint NOT NULL,
  "topic_id" bigint NOT NULL,
  "max_points" numeric(12,2) NOT NULL CHECK (max_points > 0)
);

CREATE TABLE "gamification_settings" (
  "settings_id" smallint PRIMARY KEY CHECK (settings_id = 1),
  "base_lives" integer NOT NULL CHECK (base_lives > 0),
  "life_recharge_hours" integer NOT NULL CHECK (life_recharge_hours > 0)
);

CREATE TABLE "accessories" (
  "accessory_id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "code" text UNIQUE NOT NULL CHECK (btrim(code) <> ''),
  "name" text NOT NULL CHECK (btrim(name) <> ''),
  "slot_code" text NOT NULL CHECK (btrim(slot_code) <> ''),
  "skill_id" bigint NOT NULL,
  "required_points" numeric(12,2) NOT NULL CHECK (required_points > 0),
  "is_available" boolean NOT NULL DEFAULT true
);

CREATE TABLE "student_accessories" (
  "student_id" bigint NOT NULL,
  "accessory_id" bigint NOT NULL,
  "redeemed_at" timestamptz NOT NULL DEFAULT (CURRENT_TIMESTAMP),
  PRIMARY KEY ("student_id", "accessory_id")
);

CREATE TABLE "equipped_accessories" (
  "student_id" bigint NOT NULL,
  "slot_code" text NOT NULL,
  "accessory_id" bigint NOT NULL,
  PRIMARY KEY ("student_id", "slot_code")
);

CREATE TABLE "accessory_benefits" (
  "accessory_id" bigint PRIMARY KEY,
  "kind" text NOT NULL CHECK (btrim(kind) <> ''),
  "capacity" integer NOT NULL CHECK (capacity > 0),
  "recharge_hours" integer NOT NULL CHECK (recharge_hours > 0)
);

CREATE TABLE "accessory_charge_states" (
  "student_id" bigint NOT NULL,
  "accessory_id" bigint NOT NULL,
  "remaining_charges" integer NOT NULL CHECK (remaining_charges >= 0),
  "recharge_at" timestamptz,
  CHECK ((remaining_charges = 0 AND recharge_at IS NOT NULL)
        OR (remaining_charges > 0 AND recharge_at IS NULL)),
  PRIMARY KEY ("student_id", "accessory_id")
);

CREATE TABLE "hint_uses" (
  "student_id" bigint NOT NULL,
  "mission_attempt_id" bigint NOT NULL,
  "hint_id" bigint NOT NULL,
  "accessory_id" bigint NOT NULL,
  "opened_at" timestamptz NOT NULL DEFAULT (CURRENT_TIMESTAMP),
  PRIMARY KEY ("student_id", "mission_attempt_id", "hint_id")
);

CREATE TABLE "student_life_states" (
  "student_id" bigint PRIMARY KEY,
  "lives" bigint NOT NULL CHECK (lives >= 0) DEFAULT 5,
  "base_lives" integer NOT NULL CHECK (base_lives > 0) DEFAULT 5,
  "recharge_at" timestamptz,
  "lives_recovered_in_cycle" bigint NOT NULL CHECK (lives_recovered_in_cycle >= 0) DEFAULT 0
);

CREATE TABLE "mission_life_losses" (
  "mission_attempt_id" bigint PRIMARY KEY,
  "student_id" bigint NOT NULL,
  "recorded_at" timestamptz NOT NULL DEFAULT (CURRENT_TIMESTAMP)
);

CREATE TABLE "life_recovery_activities" (
  "activity_id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "prompt" text NOT NULL CHECK (btrim(prompt) <> ''),
  "guided_solution" text NOT NULL CHECK (btrim(guided_solution) <> ''),
  "difficulty" integer NOT NULL CHECK (difficulty > 0),
  "is_available" boolean NOT NULL DEFAULT true
);

CREATE TABLE "life_recovery_attempts" (
  "recovery_attempt_id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "student_id" bigint NOT NULL,
  "activity_id" bigint NOT NULL,
  "assigned_difficulty" integer NOT NULL CHECK (assigned_difficulty > 0),
  "status" text NOT NULL CHECK (status IN ('started', 'response_submitted', 'solution_viewed', 'completed')) DEFAULT 'started',
  "response" text,
  "self_assessed_passed" boolean,
  "started_at" timestamptz NOT NULL DEFAULT (CURRENT_TIMESTAMP),
  "completed_at" timestamptz,
  "life_awarded_at" timestamptz,
  CHECK (response IS NULL OR btrim(response) <> ''),
  CHECK (status = 'started' OR response IS NOT NULL),
  CHECK ((status = 'completed' AND self_assessed_passed IS NOT NULL AND completed_at IS NOT NULL)
        OR (status <> 'completed' AND self_assessed_passed IS NULL AND completed_at IS NULL)),
  CHECK ((life_awarded_at IS NOT NULL AND status = 'completed' AND self_assessed_passed IS TRUE)
        OR (life_awarded_at IS NULL AND self_assessed_passed IS DISTINCT FROM TRUE))
);

CREATE TABLE "mission_runs" (
  "mission_run_id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "student_id" bigint NOT NULL,
  "mission_id" bigint NOT NULL,
  "status" text NOT NULL CHECK (status IN ('in_progress','passed','abandoned')),
  "created_at" timestamptz NOT NULL DEFAULT (CURRENT_TIMESTAMP)
);

CREATE TABLE "mission_attempts" (
  "mission_attempt_id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "mission_run_id" bigint NOT NULL,
  "attempt_number" integer NOT NULL CHECK (attempt_number > 0),
  "status" text NOT NULL CHECK (status IN
 ('active','saved','pending_review','failed','passed')),
  "failure_reason" text CHECK (failure_reason IN
 ('below_threshold','time_expired','abandonment')),
  "started_at" timestamptz NOT NULL DEFAULT (CURRENT_TIMESTAMP),
  "completed_at" timestamptz,
  CHECK ((status IN ('failed','passed')) = (completed_at IS NOT NULL)),
  CHECK ((status = 'failed') = (failure_reason IS NOT NULL))
);

CREATE TABLE "exercise_attempts" (
  "exercise_attempt_id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "student_id" bigint NOT NULL,
  "context" text NOT NULL CHECK (context IN ('mission','practice')),
  "question_bank_entry_id" bigint NOT NULL,
  "mission_attempt_id" bigint,
  "mission_exercise_id" bigint,
  "status" text NOT NULL CHECK (status IN
 ('active','saved','pending_review','assessed','abandoned','expired')),
  "response" jsonb,
  "configuration_snapshot" jsonb NOT NULL,
  "allowed_duration_ms" bigint CHECK (allowed_duration_ms > 0),
  "remaining_time_ms" bigint CHECK (remaining_time_ms >= 0),
  "timer_started_at" timestamptz,
  "started_at" timestamptz NOT NULL DEFAULT (CURRENT_TIMESTAMP),
  "submitted_at" timestamptz,
  "completed_at" timestamptz,
  CHECK ((context = 'mission' AND mission_attempt_id IS NOT NULL
    AND mission_exercise_id IS NOT NULL AND allowed_duration_ms IS NOT NULL
    AND remaining_time_ms IS NOT NULL)
 OR (context = 'practice' AND mission_attempt_id IS NULL AND mission_exercise_id IS NULL)),
  CHECK (remaining_time_ms IS NULL OR remaining_time_ms <= allowed_duration_ms),
  CHECK (timer_started_at IS NULL OR status = 'active'),
  CHECK (status NOT IN ('pending_review','assessed') OR submitted_at IS NOT NULL),
  CHECK ((status IN ('assessed','abandoned','expired')) = (completed_at IS NOT NULL))
);

CREATE TABLE "exercise_assessments" (
  "exercise_attempt_id" bigint PRIMARY KEY,
  "assessment_method" text NOT NULL CHECK (assessment_method IN ('automatic','teacher')),
  "percentage" numeric(5,2) NOT NULL CHECK (percentage BETWEEN 0 AND 100),
  "passing_threshold" numeric(5,2) NOT NULL CHECK (passing_threshold BETWEEN 0 AND 100),
  "passed" boolean,
  "feedback" text NOT NULL CHECK (btrim(feedback) <> ''),
  "teacher_user_id" bigint,
  "validated_at" timestamptz NOT NULL DEFAULT (CURRENT_TIMESTAMP),
  CHECK ((assessment_method = 'teacher') = (teacher_user_id IS NOT NULL))
);

CREATE TABLE "mission_checkpoints" (
  "mission_run_id" bigint NOT NULL,
  "mission_exercise_id" bigint NOT NULL,
  "exercise_attempt_id" bigint UNIQUE NOT NULL,
  PRIMARY KEY ("mission_run_id", "mission_exercise_id")
);

CREATE TABLE "content_reformulation_reviews" (
  "exercise_attempt_id" bigint PRIMARY KEY,
  "student_text" text NOT NULL CHECK (btrim(student_text) <> ''),
  "selected_context" text NOT NULL CHECK (btrim(selected_context) <> ''),
  "status" text NOT NULL CHECK (status IN ('pending','proposal_available','ai_error','validated')),
  "ai_proposal" jsonb,
  "model_reference" text,
  "instructions_version" text,
  "teacher_feedback" text,
  "teacher_percentage" numeric(5,2) CHECK (teacher_percentage BETWEEN 0 AND 100),
  "teacher_user_id" bigint,
  "validated_at" timestamptz,
  CHECK (status <> 'proposal_available' OR ai_proposal IS NOT NULL),
  CHECK ((status = 'validated' AND teacher_feedback IS NOT NULL
 AND btrim(teacher_feedback) <> '' AND teacher_percentage IS NOT NULL
 AND teacher_user_id IS NOT NULL AND validated_at IS NOT NULL)
 OR (status <> 'validated' AND teacher_feedback IS NULL
 AND teacher_percentage IS NULL AND teacher_user_id IS NULL AND validated_at IS NULL))
);

CREATE TABLE "practice_records" (
  "student_id" bigint NOT NULL,
  "practice_exercise_id" bigint NOT NULL,
  "skill_id" bigint NOT NULL,
  "exercise_attempt_id" bigint NOT NULL,
  "percentage" numeric(5,2) NOT NULL CHECK (percentage BETWEEN 60 AND 100),
  "max_points_snapshot" numeric(12,2) NOT NULL CHECK (max_points_snapshot > 0),
  "points" numeric(12,2) NOT NULL CHECK (points >= 0 AND points <= max_points_snapshot),
  "updated_at" timestamptz NOT NULL DEFAULT (CURRENT_TIMESTAMP),
  PRIMARY KEY ("student_id", "practice_exercise_id")
);

CREATE TABLE "mission_skill_contributions" (
  "student_id" bigint NOT NULL,
  "mission_id" bigint NOT NULL,
  "skill_id" bigint NOT NULL,
  "points" numeric(12,2) NOT NULL CHECK (points >= 0),
  "factor_snapshot" numeric(5,4) NOT NULL CHECK (factor_snapshot BETWEEN 0 AND 1),
  "mission_attempt_id" bigint NOT NULL,
  PRIMARY KEY ("student_id", "mission_id", "skill_id")
);

CREATE TABLE "skill_credit_entries" (
  "credit_entry_id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "event_id" text NOT NULL,
  "student_id" bigint NOT NULL,
  "skill_id" bigint NOT NULL,
  "source_kind" text NOT NULL CHECK (source_kind IN ('practice','mission')),
  "source_id" bigint NOT NULL,
  "delta" numeric(12,2) NOT NULL CHECK (delta > 0),
  "previous_contribution" numeric(12,2) NOT NULL CHECK (previous_contribution >= 0),
  "new_contribution" numeric(12,2) NOT NULL,
  "registrato_il" timestamptz NOT NULL DEFAULT (CURRENT_TIMESTAMP),
  CHECK (new_contribution = previous_contribution + delta)
);

CREATE TABLE "mission_records" (
  "student_id" bigint NOT NULL,
  "mission_id" bigint NOT NULL,
  "mission_attempt_id" bigint NOT NULL,
  "percentage" numeric(5,2) NOT NULL CHECK (percentage BETWEEN 0 AND 100),
  "updated_at" timestamptz NOT NULL DEFAULT (CURRENT_TIMESTAMP),
  PRIMARY KEY ("student_id", "mission_id")
);

CREATE TABLE "course_results" (
  "student_id" bigint NOT NULL,
  "course_id" bigint NOT NULL,
  "passed_missions" integer NOT NULL CHECK (passed_missions >= 0),
  "total_missions" integer NOT NULL CHECK (total_missions > 0),
  "percentage" numeric(5,2) CHECK (percentage BETWEEN 0 AND 100),
  "completed_at" timestamptz,
  CHECK (passed_missions <= total_missions),
  CHECK (completed_at IS NULL OR passed_missions = total_missions),
  PRIMARY KEY ("student_id", "course_id")
);

CREATE TABLE "student_first_evolutions" (
  "student_id" bigint PRIMARY KEY,
  "course_id" bigint NOT NULL,
  "skin_id" bigint NOT NULL,
  "event_id" text UNIQUE NOT NULL,
  "awarded_at" timestamptz NOT NULL DEFAULT (CURRENT_TIMESTAMP),
  "rule_version" text NOT NULL DEFAULT 'v0.1_first_course'
);

CREATE TABLE "notebook_lessons" (
  "student_id" bigint NOT NULL,
  "lesson_id" bigint NOT NULL,
  "acquired_at" timestamptz NOT NULL DEFAULT (CURRENT_TIMESTAMP),
  PRIMARY KEY ("student_id", "lesson_id")
);

CREATE TABLE "lesson_notes" (
  "student_id" bigint NOT NULL,
  "lesson_id" bigint NOT NULL,
  "text" text NOT NULL CHECK (btrim(text) <> ''),
  "version" bigint NOT NULL CHECK (version > 0) DEFAULT 1,
  "updated_at" timestamptz NOT NULL DEFAULT (CURRENT_TIMESTAMP),
  PRIMARY KEY ("student_id", "lesson_id")
);

CREATE TABLE "blog_post_favorites" (
  "student_id" bigint NOT NULL,
  "blog_post_id" bigint NOT NULL,
  "added_at" timestamptz NOT NULL DEFAULT (CURRENT_TIMESTAMP),
  PRIMARY KEY ("student_id", "blog_post_id")
);

CREATE TABLE "orientation_tests" (
  "orientation_test_id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "subject_id" bigint UNIQUE NOT NULL,
  "title" text NOT NULL
);

CREATE TABLE "orientation_questions" (
  "orientation_question_id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "orientation_test_id" bigint NOT NULL,
  "text" text NOT NULL,
  "sort_order" integer NOT NULL CHECK (sort_order>0)
);

CREATE TABLE "orientation_options" (
  "orientation_option_id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "orientation_question_id" bigint NOT NULL,
  "text" text NOT NULL,
  "sort_order" integer NOT NULL CHECK (sort_order>0)
);

CREATE TABLE "orientation_recommendations" (
  "orientation_option_id" bigint NOT NULL,
  "practice_exercise_id" bigint NOT NULL,
  "sort_order" integer NOT NULL CHECK (sort_order>0),
  PRIMARY KEY ("orientation_option_id", "practice_exercise_id")
);

CREATE INDEX "idx_user_roles_role" ON "user_roles" ("role_id");

CREATE INDEX "idx_auth_tokens_user" ON "auth_tokens" ("user_id");

CREATE INDEX "idx_auth_tokens_expiry" ON "auth_tokens" ("expires_at");

CREATE INDEX "idx_students_school" ON "students" ("school_id");

CREATE INDEX "idx_guardian_links_student" ON "guardian_links" ("student_id");

CREATE UNIQUE INDEX ON "policy_acceptances" ("user_id", "document_code", "document_version");

CREATE UNIQUE INDEX ON "skill_levels" ("skill_id", "level_number");

CREATE UNIQUE INDEX ON "skill_levels" ("skill_id", "min_points");

CREATE UNIQUE INDEX ON "skin_evolutions" ("skin_id", "stage_number");

CREATE UNIQUE INDEX ON "skin_evolutions" ("skin_id", "evolution_id");

CREATE UNIQUE INDEX ON "student_skins" ("student_id", "skin_id");

CREATE UNIQUE INDEX ON "student_skins" ("student_id", "student_skin_id");

CREATE UNIQUE INDEX ON "student_skins" ("student_skin_id", "skin_id");

CREATE INDEX "idx_student_skins_skin" ON "student_skins" ("skin_id");

CREATE INDEX "idx_student_skin_evolutions_catalog" ON "student_skin_evolutions" ("skin_id", "evolution_id");

CREATE INDEX "idx_character_selections_evolution" ON "character_selections" ("student_skin_id", "evolution_id");

CREATE UNIQUE INDEX ON "missions" ("course_id", "sort_order");

CREATE UNIQUE INDEX ON "lessons" ("mission_id", "sort_order");

CREATE UNIQUE INDEX ON "lessons" ("lesson_id", "mission_id");

CREATE UNIQUE INDEX ON "lesson_pages" ("lesson_id", "sort_order");

CREATE UNIQUE INDEX ON "question_versions" ("question_bank_entry_id", "version_number");

CREATE UNIQUE INDEX ON "question_answers" ("question_id", "sort_order");

CREATE UNIQUE INDEX ON "mission_exercises" ("mission_id", "question_bank_entry_id");

CREATE UNIQUE INDEX ON "topics" ("subject_id", "name");

CREATE UNIQUE INDEX ON "accessories" ("accessory_id", "slot_code");

CREATE UNIQUE INDEX "uq_open_life_recovery_attempt" ON "life_recovery_attempts" ("student_id");

CREATE UNIQUE INDEX ON "mission_runs" ("mission_run_id", "student_id");

CREATE UNIQUE INDEX "uq_open_mission_run" ON "mission_runs" ("student_id");

CREATE UNIQUE INDEX ON "mission_attempts" ("mission_run_id", "attempt_number");

CREATE UNIQUE INDEX ON "mission_attempts" ("mission_attempt_id", "mission_run_id");

CREATE UNIQUE INDEX "uq_open_mission_attempt" ON "mission_attempts" ("mission_run_id");

CREATE UNIQUE INDEX ON "exercise_attempts" ("exercise_attempt_id", "mission_attempt_id");

CREATE UNIQUE INDEX "uq_open_mission_exercise_attempt" ON "exercise_attempts" ("mission_attempt_id");

